    <style>
        /* RESET BÁSICO */
        * { box-sizing: border-box; margin: 0; padding: 0; }

        body {
            background-color: #ffffff; /* Fundo Branco Pedido */
            font-family: 'Open Sans', sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            color: #333;
            padding: 20px;
        }

        /* CONTAINER PRINCIPAL */
        .container {
            max-width: 600px;
            width: 100%;
            text-align: center;
            animation: fadeIn 0.8s ease-in-out;
        }

        /* LOGO */
        .logo-area {
            margin-bottom: 40px;
        }
        .logo-img {
            max-width: 200px; /* Ajuste conforme seu logo */
            height: auto;
        }

        /* TIPOGRAFIA */
        h1, h2, h3 {
            font-family: 'Helvetica', Arial, sans-serif;
            font-weight: bold;
            color: #000;
            margin-bottom: 20px;
        }

        p.question-text {
            font-size: 1.2rem;
            line-height: 1.5;
            margin-bottom: 30px;
        }

        /* OPÇÕES DO FORMULÁRIO */
        .options-grid {
            display: grid;
            gap: 15px;
        }

        .option-btn {
            background-color: #f0f0f0;
            border: none;
            border-radius: 25px; /* Cantos Arredondados */
            padding: 20px;
            font-size: 1rem;
            font-family: 'Open Sans', sans-serif;
            font-weight: normal;
            cursor: pointer;
            transition: all 0.3s ease;
            text-align: left;
            width: 100%;
        }

        .option-btn:hover {
            background-color: #e0e0e0;
            transform: translateY(-2px);
        }

        /* TELA DE COMPRA FINAL */
        .final-screen h2 {
            font-size: 1.5rem;
            color: #ff4d4d; /* Cor destacada para alerta de compra */
        }

        .cta-button {
            background-color: #000000;
            color: #ffffff;
            border: none;
            border-radius: 30px; /* Muito arredondado */
            padding: 15px 40px;
            font-size: 1.2rem;
            font-weight: bold;
            font-family: 'Helvetica', sans-serif;
            cursor: pointer;
            display: inline-block;
            margin-top: 20px;
            text-decoration: none;
            box-shadow: 0 4px 6px rgba(0,0,0,0.1);
            transition: background 0.3s;
        }

        .cta-button:hover {
            background-color: #333333;
        }

        /* ANIMAÇÃO SÚBIL */
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* Esconder elementos temporariamente se necessário */
        .hidden { display: none; }

        /* Barra de progresso simples */
        .progress-bar-container {
            width: 100%;
            background-color: #eee;
            height: 5px;
            border-radius: 5px;
            margin-bottom: 30px;
            overflow: hidden;
        }
        .progress-bar-fill {
            height: 100%;
            background-color: #000;
            width: 0%;
            transition: width 0.5s ease;
        }

    </style>
</head>
<body>

    <div class="container" id="main-container">

        <!-- Área da Logo -->
        <div class="logo-area">
            <!-- Substitua o src pela URL da sua logo ou deixe este texto se quiser apenas texto -->
            <img src="https://via.placeholder.com/200x80?text=SEU+LOGO+AQUI" alt="Logo Louans" class="logo-img">
        </div>

        <!-- Barra de Progresso -->
        <div class="progress-bar-container">
            <div class="progress-bar-fill" id="progressBar"></div>
        </div>

        <!-- CONTEÚDO DинаMICK (Gerenciado por JS) -->
        <div id="content">
            <!-- O conteúdo será injetado aqui pelo Javascript -->
        </div>

    </div>

    <script>
        // ==========================================
        // CONFIGURAÇÕES PERSONALIZáveis FAÇA AQUI
        // ==========================================

        const VIDEO_ID_YOUTUBE = ""; // Exemplo: dQw4w9WgXcQ (Deixe vazio ou cole o ID)
        const VIDEO_EMBED_URL = "https://www.youtube.com/embed/" + VIDEO_ID_YOUTUBE; // Deixei assim caso seja ID ou URL direta

        const LINK_DE_COMPRA = "#"; // Coloque o link do seu Checkout (Stripe, Hotmart, Kiwify, etc)

        // Perguntas do Formulário
        const questions = [
            {
                title: "Como você se sente sobre seu físico hoje?",
                options: [
                    "Muito contente 😁",
                    "Poderia melhorar 😊",
                    "Nada contente 😑",
                    "Muito mal 😔"
                ]
            },
            {
                title: "Você já tentou resolver isso antes? Como foi?",
                options: [
                    "Sim, funcionou bem 🏆",
                    "Sim, tentei mas desistiu 😓",
                    "Não tentei nada ainda 🤷‍♂️",
                    "Gosto disso mais 😒"
                ]
            },
            {
                title: "O que te impede de mudar?",
                options: [
                    "Falta de tempo ⏳",
                    "Falta de dinheiro 💸",
                    "Não sei onde começar 🗺️",
                    "Estou ansioso pra mudar ❤️"
                ]
            },
            {
                title: "Qual seria o seu maior objetivo neste mês?",
                options: [
                    "Ter energia total 🔋",
                    "Perder peso saudável ⚖️",
                    "Ter mais confiança 🦁",
                    "Além do previsto ⚡"
                ]
            }
        ];

        // ==========================================
        // LÓGICA DO SISTEMA (NÃO APAGUE NESTA PARTE)
        // ==========================================

        let currentStep = 0;
        const contentDiv = document.getElementById('content');
        const progressBar = document.getElementById('progressBar');
        const totalSteps = questions.length + 2; // 4 perguntas + Vídeo + Compra

        function showStep() {
