                // TELA DO VÍDEO
                showVideoUI();
            } else if (currentStep === totalSteps) {
                // TELA DE COMPRA FINAL
                showBuyUI();
            }
        }

        function showQuestionUI(qIndex) {
            const q = questions[qIndex];
            let html = `
                <h1>${q.title}</h1>
                <div class="options-grid">
            `;

            q.options.forEach(opt => {
                html += `<button class="option-btn" onclick="nextStep(this)"> ${opt} </button>`;
