            // Se você colocar ID no campo VIDEO_ID_YOUTUBE, carregará.
            // Se não, usaremos o placeholder.
            let iframeSrc = VIDEO_EMBED_URL || "https://www.youtube.com/embed/dQw4w9WgXcQ?autoplay=1";
