            // Vamos fazer um loading visual simples ou direto.
            // Para garantir funcionamento, recomendo adicionar autoplay=1 apenas após clique anterior, 
            // mas aqui vamos deixar simples para fluxo linear.
            iframeSrc += "?autoplay=1"; 

            let html = `
                <h2>Você merece a melhor solução!</h2>
                <p>Assista ao vídeo abaixo para ver por onde começa:</p>
                <iframe width="100%" height="350" src="${iframeSrc}" frameborder="0" allowfullscreen></iframe>
