            element.style.backgroundColor = "#f0f0f0";

            currentStep++;
            showStep();

            // Se chegar no fim do formulário (última pergunta), libera o clique novamente na próxima
            if(currentStep > totalSteps) {
                // Reabilitar lógica se necessário (ex: voltar para o primeiro)
            }
        }

        // Inicia o processo
        window.onload = () => {
            showStep();
        };

