        function getVal(id) {
            let val = parseFloat(document.getElementById(id).value);
            return isNaN(val) ? null : val;
        }

        // Função para formatar número com casas decimais (opcional)
        function formatNumber(num) {
            return num.toFixed(3);
        }

        // --- CÁLCULO DE LEI DE OHM ---
        function calcularOhm() {
            // Pegar valores
            const vIn = getVal('ohm_v');
            const iIn = getVal('ohm_i');
            const rIn = getVal('ohm_r');

            let resultado = null;
            let mensagem = "";

            // Lógica: Se temos V e I -> Encontra R
            if (!isNaN(vIn) && !isNaN(iIn)) {
                resultado = vIn / iIn;
                mensagem = `${formatNumber(resultado)} Ω`;
            }
            // Lógica: Se temos V e R -> Encontra I
            else if (!isNaN(vIn) && !isNaN(rIn)) {
                resultado = vIn / rIn;
                mensagem = `${formatNumber(resultado)} A`;
            }
            // Lógica: Se temos I e R -> Encontra V
            else if (!isNaN(iIn) && !isNaN(rIn)) {
                resultado = iIn * rIn;
                mensagem = `${formatNumber(resultado)} V`;
            }
            else {
                mensagem = "Falta informação! Digite 2 dos 3 campos.";
            }

            // Atualizar UI
            document.getElementById('valorResultadoOhm').innerText = mensagem;
            document.getElementById('resultadoOhm').style.display = 'block';

            alert(mensagem.replace(/\$/g, '')); // Alerta simples na tela
        }

