        function calcularPotencia() {
            const rIn = getVal('p_r');
            const vIn = getVal('p_v');
            const iIn = getVal('p_i');

            let resultado = null;
            let mensagem = "";

            // Lógica: Se tiver R e V -> P = V*R/R = V²/R ?? Não, P=VI. Preciso de I.
            // Mas posso derivar. Se tiver R e V, I = V/R. Logo P = (V/V)*V? Não, P = V*I.
            // Vamos simplificar: P = V * I (necessário V e I)
            // OU P = V * (V/R) = V²/R (necessário V e R)
            // OU P = (I*R)*I = I²*R (necessário I e R)

            if (!isNaN(vIn) && !isNaN(iIn)) {
                resultado = vIn * iIn;
                mensagem = `${formatNumber(resultado)} W`;
            }
            else if (!isNaN(vIn) && !isNaN(rIn)) {
                // Derivado: I = V/R -> P = V * (V/R)
                if(rIn !== 0) resultado = (vIn * vIn) / rIn;
                else mensagem = "Erro: Resistência 0";
                mensagem += " (Baseado em V e R)";
            }
            else if (!isNaN(iIn) && !isNaN(rIn)) {
                // Derivado: V = I*R -> P = (I*R)*I
                if(iIn !== 0) resultado = (iIn * iIn) * rIn;
                else mensagem = "Erro: Corrente 0";
                mensagem += " (Baseado em I e R)";
            }
            else {
                mensagem = "Precisa de pelo menos V, I e R para calcular.";
            }

            document.getElementById('valorResultadoPotencia').innerText = mensagem;
            document.getElementById('resultadoPotencia').style.display = 'block';

            alert(mensagem.replace(/\$/g, ''));
        }

